import pandas as pd

def clean(df):
    df = df.copy()

    for col in ['penguin_id', 'species', 'island', 'sex']:
        if col in df.columns:
            df[col] = df[col].astype('string').str.strip()

    if 'species' in df.columns:
        species_map = {'adelie': 'Adelie', 'chinstrap': 'Chinstrap', 'gentoo': 'Gentoo'}
        df['species'] = df['species'].map(
            lambda x: species_map.get(str(x).strip().lower(), x) if pd.notna(x) else x
        )

    if 'island' in df.columns:
        island_map = {'biscoe': 'Biscoe', 'dream': 'Dream', 'torgersen': 'Torgersen'}
        df['island'] = df['island'].map(
            lambda x: island_map.get(str(x).strip().lower(), x) if pd.notna(x) else x
        )

    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')

    if 'body_mass_g' in df.columns:
        mask = df['body_mass_g'] > 6500
        df.loc[mask, 'body_mass_g'] = df.loc[mask, 'body_mass_g'] / 1000.0

    if 'sex' in df.columns:
        df['sex'] = df['sex'].astype('string').str.strip().str.lower()
        df.loc[~df['sex'].isin(['male', 'female']), 'sex'] = pd.NA

    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['island'])
    counts = d.groupby('island', dropna=True).size().sort_index()
    return {str(k): int(v) for k, v in counts.items()}
